//! 独立 Chromium 155 img→sRGB Canvas 样本：真实 mft2、曲线、暗部和 alpha。
use super::*;
use base64::Engine;

#[test]
fn surface_webp_icc_lut_matches_chromium_through_real_child() {
    for (encoded, expected) in CASES {
        let bytes = base64::engine::general_purpose::STANDARD
            .decode(encoded)
            .unwrap();
        let image = Image::from_surface(&bytes, "image/webp", None, || false).unwrap();
        assert_eq!((image.width, image.height), (8, 1));
        assert_eq!(image.pixels.len(), expected.len());
        for (actual, rgba) in image.pixels.chunks_exact(4).zip(expected.chunks_exact(4)) {
            assert_eq!(actual[3], rgba[3]);
            for (target, channel) in [(0, 2), (1, 1), (2, 0)] {
                let value = ((u16::from(rgba[channel]) * u16::from(rgba[3]) + 127) / 255) as u8;
                assert!(
                    actual[target].abs_diff(value) <= 1,
                    "{actual:?} vs {rgba:?}"
                );
            }
        }
    }
}

// 自建 ICC 仅含 A2B0(mft2) 和 wtpt，没有 matrix/TRC 快路；LittleCMS 独立接受。
// curve0 输出表为 identity；curve1 为 [0,8000,30000,50000,65535]，覆盖截断附近。
const CASES: &[(&str, [u8; 32])] = &[
    // otter-lut-curve0-alpha255
    ("", [160, 137, 89, 255, 89, 160, 124, 255, 124, 89, 170, 255, 137, 137, 137, 255, 0, 0, 0, 255, 188, 188, 188, 255, 34, 50, 71, 255, 186, 179, 172, 255]),
    // otter-lut-curve0-alpha128
    ("", [159, 137, 90, 128, 90, 159, 124, 128, 124, 90, 169, 128, 137, 137, 137, 128, 0, 0, 0, 128, 187, 187, 187, 128, 34, 50, 72, 128, 185, 179, 171, 128]),
    // otter-lut-curve1-alpha255
    ("", [120, 101, 61, 255, 0, 132, 85, 255, 79, 63, 138, 255, 98, 98, 98, 255, 0, 0, 0, 255, 179, 181, 171, 255, 21, 33, 49, 255, 177, 169, 146, 255]),
    // otter-lut-curve1-alpha128
    ("", [120, 102, 62, 128, 0, 131, 86, 128, 78, 64, 137, 128, 98, 98, 98, 128, 0, 0, 0, 128, 179, 181, 171, 128, 22, 34, 50, 128, 177, 169, 145, 128]),
    // otter-lut-curve2-alpha255
    ("", [53, 52, 59, 255, 47, 46, 53, 255, 51, 49, 56, 255, 71, 69, 78, 255, 0, 0, 0, 255, 190, 185, 207, 255, 0, 0, 1, 255, 164, 160, 180, 255]),
    // otter-lut-curve2-alpha128
    ("", [54, 52, 60, 128, 48, 46, 52, 128, 50, 50, 56, 128, 72, 70, 78, 128, 0, 0, 0, 128, 189, 185, 207, 128, 0, 0, 0, 128, 165, 161, 179, 128]),
];
